export default function LandingScreen() {
  const router = useRouter();

  return (
    <View className="flex-1" style={{ backgroundColor: "#F5F2EC" }}>
      <StatusBar barStyle="dark-content" backgroundColor="#F5F2EC" />

      {/* Header */}
      <View className="items-center pt-14 pb-2">
        <RNText className="text-[13px] text-gray-400 tracking-[2px]">UniMejores</RNText>
      </View>

      {/* Characters area */}
      <View className="flex-1" style={{ position: "relative" }}>
        {/* Wave background — sits at the bottom of the characters zone */}
        <View style={{ position: "absolute", bottom: 0, left: 0, right: 0, height: 220 }}>
          <SvgXml xml={BG_SVG} className="w-screen h-auto" />
        </View>

        {/* Characters side by side, anchored to bottom */}
        <View
          className="flex-row items-end justify-around"
          style={{ position: "absolute", bottom: 0, left: 0, right: 0 }}
        >
          <SvgXml xml={HOMBRE_SVG} width={170} height={230} />
          <SvgXml xml={MUJER_SVG} width={170} height={230} />
        </View>
      </View>

      {/* Bottom content */}
      <View className="px-8 pt-6 pb-12 gap-5">
        <View className="gap-2">
          <RNText className="text-[34px] font-bold text-[#1E1E2E] text-center leading-[42px]">
            Califica a tu{"\n"}Compañero
          </RNText>
          <RNText className="text-[14px] text-gray-400 text-center italic leading-6">
            En esta vida hay personas que{"\n"}se merecen feedback para{"\n"}mejorar.
          </RNText>
        </View>

        <Button onPress={() => router.push("/login" as RelativePathString)}>
          <Text>INICIAR SESION</Text>
        </Button>
      </View>
    </View>
  );
}
